def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')

    if not uri or uri.isspace():
        raise ValueError('uri cannot be empty or whitespace')

    parsed = urlparse.urlparse(uri)

    if not parsed.scheme or not parsed.netloc:
        raise ValueError('uri must be an absolute URI')

    scheme = parsed.scheme.lower()

    if host:
        netloc = host.lower()
    else:
        netloc = parsed.hostname
        if not netloc:
            raise ValueError('uri must have a valid hostname')

        netloc = netloc.lower()

        if parsed.port:
            port = parsed.port
            if port <= 0 or port >= 65536:
                raise ValueError('port must be between 1 and 65535')

            default_ports = {'http': 80, 'https': 443}
            if port != default_ports.get(scheme):
                netloc = f'{netloc}:{port}'

    path = parsed.path or '/'

    path = urlparse.quote(path, safe='/~')

    return f'{scheme}://{netloc}{path}'
